from .models import GovernanceReport, Provenance
class GovernanceReportBuilder:
    def build(self,tenant_id,framework_id,controls,readiness,drifts,period=None,executive_risk_references=None):
        statuses={"compliant":[],"partial":[],"non_compliant":[],"insufficient_evidence":[],"unknown":[]}
        for c in controls:
            s=str(getattr(c,"status","unknown")).lower(); key="compliant" if s in {"implemented","compliant","effective","passed"} else "non_compliant" if s in {"failed","non_compliant"} else "partial" if s in {"partial","partially_compliant"} else "unknown"; statuses[key].append(getattr(c,"control_id",""))
        gaps=list(getattr(readiness,"gaps",[]) or []); insufficient={g.get("control_id") for g in gaps if isinstance(g,dict) and g.get("control_id")}; statuses["insufficient_evidence"]=[x for x in statuses["unknown"] if x in insufficient]; statuses["unknown"]=[x for x in statuses["unknown"] if x not in insufficient]; refs=[getattr(x,"reference","") for x in getattr(readiness,"evidence",[]) if getattr(x,"reference","")] if hasattr(readiness,"evidence") else []
        return GovernanceReport(tenant_id,frameworks_covered=[framework_id],control_totals={k:len(v) for k,v in statuses.items()},compliant_controls=statuses["compliant"],partially_compliant_controls=statuses["partial"],non_compliant_controls=statuses["non_compliant"],insufficient_evidence_controls=statuses["insufficient_evidence"],unknown_controls=statuses["unknown"],evidence_coverage=getattr(readiness,"completeness_score",0.0),audit_readiness=getattr(readiness,"readiness_score",0.0),drift_summary={"count":len(drifts),"high":sum(getattr(x,"severity","")=="high" for x in drifts)},unresolved_gap_summary=gaps,historical_trend={"status":"advisory"},executive_risk_references=executive_risk_references or [],evidence_references=refs,reporting_period=period or {},provenance=[Provenance("compliance_governance","", "control statuses supplied by authoritative assessment"),Provenance("compliance_monitoring","", "readiness and drift supplied by monitoring")])
